            arena_id: m.arena_id,
            wave_id: m.wave_id,
            round_num: m.round_num ?? 0,
            kind: m.kind,
            source_agent_key: m.source_agent_key || "",
            text: m.text || "",
            raw_text: m.raw_text || "",
            control_signal: m.control_signal || "continue",
            metadata_json: m.metadata_json || "{}",
            created_at: m.created_at ?? Date.now()
