class LeaseManager {
  leases = new Map;
  acquireLease(nodeId, durationMs = 30000) {
    if (this.isLeased(nodeId)) {
      return false;
    }
    this.leases.delete(nodeId);
    const now5 = Date.now();
    this.leases.set(nodeId, {
      nodeId,
      acquiredAt: now5,
      expiresAt: now5 + durationMs
    });
    return true;
  }
  releaseLease(nodeId) {
    this.leases.delete(nodeId);
  }
  isLeased(nodeId) {
    const lease = this.leases.get(nodeId);
    if (!lease)
      return false;
    if (Date.now() >= lease.expiresAt) {
      this.leases.delete(nodeId);
      return false;
    }
    return true;
  }
  getActiveLeases() {
    this.cleanup();
    return Array.from(this.leases.values());
  }
  cleanup() {
    const now5 = Date.now();
    for (const [nodeId, lease] of this.leases) {
      if (now5 >= lease.expiresAt) {
        this.leases.delete(nodeId);
      }
    }
  }
}
function getReadyNodes(nodes, graph, options2) {
  const leaseManager = options2?.leaseManager;
  const teamPolicy = options2?.teamPolicy;
  const nodeTeamMap = options2?.nodeTeamMap;
  const maxActivePerRun = teamPolicy?.maxActivePerRun ?? 12;
  const maxActivePerTeam = teamPolicy?.maxActivePerTeam ?? 4;
  let activeCount = 0;
  const activePerTeam = new Map;
  for (const node3 of nodes) {
    const isActive = node3.status === "active";
    const isLeased = leaseManager ? leaseManager.isLeased(node3.id) : false;
    if (isActive || isLeased) {
      activeCount++;
      if (nodeTeamMap) {
        const teamId = nodeTeamMap.get(node3.id);
        if (teamId) {
          activePerTeam.set(teamId, (activePerTeam.get(teamId) || 0) + 1);
        }
      }
    }
  }
  const readyNodes = [];
  for (const node3 of nodes) {
    if (node3.status !== "pending" && node3.status !== "retryable") {
      continue;
    }
    if (leaseManager && leaseManager.isLeased(node3.id)) {
      continue;
    }
    if (!graph.isReady(node3.id)) {
      continue;
    }
    if (activeCount + readyNodes.length >= maxActivePerRun) {
      break;
    }
    if (nodeTeamMap && teamPolicy) {
      const teamId = nodeTeamMap.get(node3.id);
      if (teamId) {
        const currentTeamActive = activePerTeam.get(teamId) || 0;
        const alreadyAddedForTeam = readyNodes.filter((rn2) => nodeTeamMap.get(rn2.id) === teamId).length;
        if (currentTeamActive + alreadyAddedForTeam >= maxActivePerTeam) {
          continue;
        }
      }
    }
    readyNodes.push(node3);
  }
  return readyNodes;
}

