  ensureColumn2(db, "sources_current", "provider_connection_id", "ALTER TABLE sources_current ADD COLUMN provider_connection_id TEXT");
  ensureColumn2(db, "sources_current", "import_mode", "ALTER TABLE sources_current ADD COLUMN import_mode TEXT");
