  db.exec(`CREATE INDEX IF NOT EXISTS idx_run_node_items_item ON run_node_items_current(work_item_id)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_events_run_seq   ON events(run_id, stream_seq)`);
