function createOpencodeEvents(opencodeUrl2) {
  const handlers = new Set;
  let abortController = null;
  let closed = false;
  let reconnectTimer;
  let reconnectDelay = 1000;
  async function connect() {
    if (closed)
      return;
    abortController = new AbortController;
    try {
      const res = await fetch(`${opencodeUrl2}/global/event`, {
        headers: opencodeHeaders({ Accept: "text/event-stream" }),
        signal: abortController.signal
      });
      if (!res.ok || !res.body)
        throw new Error(`Failed to connect to opencode events: ${res.status}`);
      reconnectDelay = 1000;
      const reader = res.body.getReader();
      const decoder3 = new TextDecoder;
      let buffer = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done)
          break;
        buffer += decoder3.decode(value, { stream: true });
        const lines2 = buffer.split(`
`);
        buffer = lines2.pop() ?? "";
        for (const line of lines2) {
          if (!line.startsWith("data: "))
            continue;
          const raw4 = line.slice(6).trim();
          if (!raw4)
            continue;
          try {
            const data = JSON.parse(raw4);
            for (const handler2 of handlers) {
              try {
                handler2(data);
              } catch {}
            }
          } catch {}
        }
      }
    } catch (err) {
      if (closed)
        return;
      if (err?.name === "AbortError")
        return;
      console.error("[opencode-events] connection lost, reconnecting in", reconnectDelay, "ms");
    }
    if (!closed) {
      reconnectTimer = setTimeout(() => {
        reconnectDelay = Math.min(reconnectDelay * 2, 30000);
        connect();
      }, reconnectDelay);
    }
  }
  connect();
  return {
    on(fn2) {
      handlers.add(fn2);
    },
    off(fn2) {
      handlers.delete(fn2);
    },
    close() {
      closed = true;
      if (reconnectTimer)
        clearTimeout(reconnectTimer);
      abortController?.abort();
    }
  };
}

